window.MEASURES=[{"key":"share","name":"Muslim share of residents","group":"Faith & community","unit":"%","description":"Estimated share of residents identifying as Muslim. Religious affiliation is measured using censuses, surveys and demographic estimates.","source":"Pew Research Center","url":"https://www.pewresearch.org/dataset/dataset-of-global-religious-composition-estimates-for-2010-and-2020/","decimals":1},{"key":"people","name":"Muslim population","group":"Faith & community","unit":"people","description":"Estimated number of residents who identify as Muslim. Pew rounds counts to 10,000 and reports small estimates as upper bounds.","source":"Pew Research Center","url":"https://www.pewresearch.org/dataset/dataset-of-global-religious-composition-estimates-for-2010-and-2020/","decimals":0},{"key":"prices","name":"Household price level","group":"Costs & work","unit":"U.S. = 100","description":"Price of a comparable basket of household goods and services relative to the United States. An index of 32 means a basket priced at $100 in the U.S. costs about $32 at the reference exchange rate. These national averages include household and nonprofit consumption. Exchange rates affect the index, and household budgets vary with city, spending patterns and income.","source":"World Bank, International Comparison Program and World Development Indicators","url":"https://data.worldbank.org/indicator/PA.NUS.PRVT.PLI","decimals":1},{"key":"internet","name":"Residents using the internet","group":"Daily infrastructure","unit":"%","description":"Share of people who went online in the preceding three months, using any device or connection. This indicator measures recent use. Connection speed, subscription prices and mobile coverage vary by location.","source":"International Telecommunication Union, via World Development Indicators","url":"https://data.worldbank.org/indicator/IT.NET.USER.ZS","decimals":1},{"key":"urban","name":"Residents in urban areas","group":"Daily infrastructure","unit":"%","description":"Share of residents living in areas each country classifies as urban. Countries apply their own definitions of urban areas, so the figures are only partly comparable.","source":"United Nations Population Division, World Urbanization Prospects, via World Development Indicators","url":"https://data.worldbank.org/indicator/SP.URB.TOTL.IN.ZS","decimals":1},{"key":"life","name":"Life expectancy at birth","group":"Healthcare","unit":"years","description":"Expected years of life for a newborn if the year’s age-specific mortality rates held throughout their life. These population estimates describe the whole country across sexes and regions.","source":"United Nations Population Division, national statistical offices and Eurostat, via World Development Indicators","url":"https://data.worldbank.org/indicator/SP.DYN.LE00.IN","decimals":1},{"key":"uhc","name":"Coverage of essential health services","group":"Healthcare","unit":"/100","description":"Index of coverage across essential health services. Eligibility and insurance for a newly arrived family depend on local rules.","source":"WHO & World Bank","url":"https://data.worldbank.org/indicator/SH_UHC_SCI","decimals":1},{"key":"oop","name":"Health spending paid out of pocket","group":"Healthcare","unit":"%","description":"Share of current national health spending paid directly by households. This is a system-wide share, not a quote for insurance.","source":"WHO","url":"https://data.worldbank.org/indicator/SH.XPD.OOPC.CH.ZS","decimals":1},{"key":"dpt","name":"Childhood DPT vaccination","group":"Children & schools","unit":"%","description":"Share of children aged 12–23 months who received three doses of diphtheria, pertussis and tetanus vaccine.","source":"WHO & UNICEF","url":"https://data.worldbank.org/indicator/SH.IMM.IDPT","decimals":0},{"key":"mort","name":"Under-five mortality","group":"Children & schools","unit":"per 1,000","description":"Deaths before age five per 1,000 live births, based on population-level estimates.","source":"UN Inter-agency Group for Child Mortality Estimation","url":"https://data.worldbank.org/indicator/SH.DYN.MORT","decimals":1},{"key":"schoolyears","name":"Duration of compulsory education","group":"Children & schools","unit":"years","description":"Number of years of compulsory schooling in the national education system. Confirm admissions, language and enrolment requirements with the school district.","source":"UNESCO Institute for Statistics","url":"https://data.worldbank.org/indicator/SE.COM.DURS","decimals":0},{"key":"teachers","name":"Primary pupils per teacher","group":"Children & schools","unit":"pupils","description":"Primary pupils enrolled per primary teacher nationally. Actual class sizes and school fees vary by district.","source":"UNESCO Institute for Statistics","url":"https://data.worldbank.org/indicator/SE.PRM.ENRL.TC.ZS","decimals":1},{"key":"jobs","name":"Unemployment","group":"Costs & work","unit":"%","description":"Share of the labour force without work, available and seeking employment. Modelled ILO estimate.","source":"International Labour Organization","url":"https://data.worldbank.org/indicator/SL.UEM.TOTL.ZS","decimals":1},{"key":"homicide","name":"Intentional homicide rate","group":"Safety & environment","unit":"per 100k","description":"Intentional killings per 100,000 residents. This measures one form of violence nationally. Neighbourhood conditions vary.","source":"UN Office on Drugs and Crime","url":"https://data.worldbank.org/indicator/VC.IHR.PSRC.P5","decimals":2},{"key":"air","name":"Annual PM2.5 exposure","group":"Safety & environment","unit":"µg/m³","description":"Population-weighted average concentration of fine particulate matter. Lower concentrations indicate cleaner air.","source":"Global Burden of Disease Study · WDI","url":"https://data.worldbank.org/indicator/EN.ATM.PM25.MC.M3","decimals":1},{"key":"water","name":"Safely managed drinking water","group":"Safety & environment","unit":"%","description":"Share using a drinking water source on premises, available when needed and free from contamination.","source":"WHO & UNICEF Joint Monitoring Programme","url":"https://data.worldbank.org/indicator/SH.H2O.SMDW.ZS","decimals":1}];
